def try_call_method(obj, method_name, **kwargs):
    method = getattr(obj, method_name, None)
    if method is None:
        call = getattr(obj, "call", None)
        if call is None:
            return False
        try:
            call(method_name, args=kwargs)
        except Exception:
            return False
        return True
    try:
        method(**kwargs)
    except TypeError:
        try:
            method(*kwargs.values())
        except Exception:
            return False
    except Exception:
        return False
    return True


