    return value


def get_mapping_or_attr_value(obj, key):
    if isinstance(obj, dict):
        if key not in obj:
            raise AttributeError(key)
        return obj[key]
    if hasattr(obj, "get_editor_property"):
        return obj.get_editor_property(key)
    return getattr(obj, key)


